theme.css:
/* theme: The Counterweight | A defensive day of corporate restructuring, late-billion-dollar campaign blitzes, and market anxiety — the design balances weight and pressure like a market teetering on a fulcrum. */
/* layout: hero=split; political-news=numbered/stack; financial-news=banner/stack; entertainment-news=outline/grid-2; music-releases=tile/masonry; stock-analysis=stat/grid-3; outlook=timeline/stack */

.diary-page {
  --paper: #1a1d24;
  --paper-alt: #232833;
  --ink: #f2f0ea;
  --ink-soft: #c9c6bd;
  --muted: #9a968f;
  --accent: #d9a441;
  --accent-ink: #1a1d24;
  --rule: #3a3f4a;
  --font-display: var(--ff-unbounded), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), sans-serif;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #12141a;
    --paper-alt: #1b1f28;
    --ink: #f2f0ea;
    --ink-soft: #c9c6bd;
    --muted: #9a968f;
    --accent: #d9a441;
    --accent-ink: #12141a;
    --rule: #333a45;
  }
}

.diary-page {
  background: var(--paper);
  color: var(--ink-soft);
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 2px solid var(--accent);
  position: relative;
}

.diary-page .diary-hero::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--accent) 0%, var(--accent) 40%, transparent 40%, transparent 60%, var(--accent) 60%, var(--accent) 100%);
}

.diary-page .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
  position: relative;
}

.diary-page .diary-crumbs a {
  font-family: var(--font-ui);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  color: var(--muted);
}

.diary-page .diary-crumbs a:hover {
  color: var(--accent);
}

.diary-page .diary-kicker {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  margin-top: 2.5rem;
}

.diary-page .diary-title {
  font-family: var(--font-display);
  font-size: clamp(2.25rem, 6vw, 4.5rem);
  font-weight: 700;
  line-height: 1.05;
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: var(--ink);
  max-width: 22ch;
}

.diary-page .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.35rem);
  line-height: 1.6;
  color: var(--ink-soft);
  max-width: 42rem;
  border-left: 3px solid var(--accent);
  padding-left: 1.25rem;
  margin-top: 1.5rem;
}

.diary-page .diary-theme-note {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 1.75rem;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  font-weight: 600;
  padding: 0.15rem 0.7rem;
  border-radius: 0;
  clip-path: polygon(0 0, 100% 0, 95% 100%, 5% 100%);
}

.diary-page .diary-body {
  padding-bottom: 4rem;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  font-family: var(--font-ui);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--accent);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border: 0;
    background: none;
  }

  .diary-page .diary-toc-list {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-link {
    border-left: 2px solid transparent;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  padding-block: 3rem;
  position: relative;
}

.diary-page .diary-section-head {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
}

.diary-page .diary-section-number {
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--accent);
}

.diary-page .diary-section-title {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.5rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose {
  font-size: 1.12rem;
  line-height: 1.75;
  color: var(--ink-soft);
}

.diary-page .diary-prose h3 {
  font-family: var(--font-ui);
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-prose h4 {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-prose a {
  font-family: var(--font-ui);
  font-size: 0.68em;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
  white-space: normal !important;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  color: var(--ink);
}

.diary-page .diary-prose hr {
  border-top-color: var(--rule);
}

.diary-page .diary-prose code,
.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

/* Card styles */
.diary-page .diary-card--numbered .diary-card-inner {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1.5rem;
  row-gap: 0.75rem;
  padding: 1.5rem 0;
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-card--numbered .diary-card-index {
  font-family: var(--font-display);
  font-size: 2.75rem;
  font-weight: 700;
  line-height: 0.9;
  color: var(--accent);
  grid-row: 1 / span 3;
}

.diary-page .diary-card--numbered .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-left: 4px solid var(--accent);
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  padding: 0.9rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  padding: 1.5rem;
  background: var(--paper);
  box-shadow: 4px 4px 0 var(--rule);
}

.diary-page .diary-card--outline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  padding: 1.5rem;
  border-left: 3px solid var(--accent);
}

.diary-page .diary-card--tile .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  padding-top: 1.25rem;
}

.diary-page .diary-card-figure {
  font-family: var(--font-display);
  font-size: clamp(2rem, 10cqi, 3rem);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--accent);
}

.diary-page .diary-card--stat .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
  position: relative;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  content: "";
  position: absolute;
  left: 0.4rem;
  top: 0;
  bottom: -1.5rem;
  width: 2px;
  background: var(--accent);
  opacity: 0.5;
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  content: "";
  position: absolute;
  left: 0;
  top: 0.45rem;
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--timeline .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.25rem;
  font-weight: 700;
  text-transform: uppercase;
  color: var(--ink);
}

.diary-page .diary-card-thread {
  font-family: var(--font-ui);
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  border: 1px solid var(--accent);
  color: var(--accent);
  border-radius: 0;
  padding: 0.2rem 0.6rem;
  background: transparent;
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Layout tweaks */
.diary-page .diary-stories--stack {
  max-width: 46rem;
}

.diary-page .diary-stories--grid-2,
.diary-page .diary-stories--grid-3 {
  gap: 1.75rem;
}

.diary-page .diary-stories--masonry {
  columns: 2 19rem;
  column-gap: 1.75rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  margin-bottom: 1.75rem;
  break-inside: avoid;
}

.diary-page .diary-stories--grid-3 {
  gap: 1.25rem;
}

/* Sparkline market cards */
.diary-page .diary-markets-wrap {
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  font-family: var(--font-ui);
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}

.diary-page .diary-markets {
  gap: 0.75rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-top: 2px solid var(--accent);
  padding: 0.85rem 0.9rem 0.65rem;
}

.diary-page .diary-spark-label {
  font-size: 0.75rem;
  color: var(--muted);
}

.diary-page .diary-spark-value {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--ink);
}

.diary-page .diary-spark-change {
  font-size: 0.75rem;
  font-weight: 600;
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

/* Footer */
.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
  font-family: var(--font-ui);
  font-size: 0.85rem;
  color: var(--muted);
}

.diary-page .diary-footer a {
  color: var(--ink);
  font-weight: 600;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}

/* Subtle entrance for section heads */
.diary-page .diary-section-head {
  animation: diary-slide-up 0.5s ease-out both;
}

@keyframes diary-slide-up {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page .diary-section-head {
    animation: none;
  }
}

/* Desktop split hero refinement */
@media (min-width: 1024px) {
  .diary-page[data-hero="split"] .diary-hero-inner {
    grid-template-columns: minmax(0, 1.2fr) minmax(0, 0.8fr);
    column-gap: 3rem;
    align-items: end;
  }

  .diary-page .diary-summary {
    margin-top: 0;
  }

  .diary-page .diary-theme-note {
    margin-top: 1.25rem;
  }
}

/* Card hover: subtle lift for outline cards */
.diary-page .diary-card--outline .diary-card-inner {
  transition: transform 200ms ease, box-shadow 200ms ease;
}

.diary-page .diary-card--outline .diary-card-inner:hover {
  transform: translateY(-3px);
  box-shadow: 6px 6px 0 var(--accent);
}
